// Extracted existing GiftVerse playtest hero frames. Original source: prior GiftVerse-Playtest.html.
// These are existing assets, not newly generated or complete animation sets.
export const heroAssetData = {"hero_idle_4.png":"data:image/png;base64,","hero_attack_7.png":"data:image/png;base64,","hero_idle_7.png":"data:image/png;base64,","hero_idle_5.png":"data:image/png;base64,","hero_attack_6.png":"data:image/png;base64,","hero_idle_6.png":"data:image/png;base64,","hero_idle_2.png":"data:image/png;base64,","hero_attack_1.png":"data:image/png;base64,","hero_attack_8.png":"data:image/png;base64,","hero_idle_8.png":"data:image/png;base64,","hero_attack_2.png":"data:image/png;base64,","hero_attack_3.png":"data:image/png;base64,","hero_attack_4.png":"data:image/png;base64,","hero_idle_3.png":"data:image/png;base64,","hero_idle_1.png":"data:image/png;base64,","hero_attack_5.png":"data:image/png;base64,"};

export const heroAnimationCatalog = {
  idle: ["hero_idle_1.png","hero_idle_2.png","hero_idle_3.png","hero_idle_4.png","hero_idle_5.png","hero_idle_6.png","hero_idle_7.png","hero_idle_8.png"],
  attack: ["hero_attack_1.png","hero_attack_2.png","hero_attack_3.png","hero_attack_4.png","hero_attack_5.png","hero_attack_6.png","hero_attack_7.png","hero_attack_8.png"]
};

export function loadHeroAnimation(animation = "idle") {
  const names = heroAnimationCatalog[animation];
  if (!names) throw new Error(`Unknown hero animation: ${animation}`);
  return Promise.all(names.map(name => new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve({ name, image });
    image.onerror = () => reject(new Error(`Could not load hero frame: ${name}`));
    image.src = heroAssetData[name];
  })));
}

const loadedAnimations = new Map();
export function getHeroAnimation(animation = "idle") {
  if (!loadedAnimations.has(animation)) {
    loadedAnimations.set(animation, loadHeroAnimation(animation));
  }
  return loadedAnimations.get(animation);
}

export async function drawHeroFrame(ctx, animation, frameIndex, x, groundY, height = 88, flipX = false) {
  const frames = await getHeroAnimation(animation);
  const entry = frames[((frameIndex % frames.length) + frames.length) % frames.length];
  const { image } = entry;
  const width = image.naturalWidth * (height / image.naturalHeight);
  ctx.save();
  ctx.translate(x, groundY);
  if (flipX) ctx.scale(-1, 1);
  ctx.drawImage(image, -width / 2, -height, width, height);
  ctx.restore();
  return entry.name;
}
